            <div style={{ position: 'absolute', inset: 0, width: `${anim * 100}%`, minWidth: anim > 0 ? 12 * s : 0, borderRadius: 99, background: `linear-gradient(90deg, ${lighten(accent, 0.2)}, ${accent})` }} />
          </div>
