            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 4 * s }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 5 * s, fontSize: 11 * s, fontWeight: 600, color: accent }}>
